// Player controls: double-tap seek, speed button, swipe -> native bridge, PiP layout, popup of toolbar.
const { chromium } = require('playwright'); const fs = require('fs'); const path = require('path')
const ENGINE = path.resolve(__dirname, '../android/app/src/main/assets/engine.js')
;(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required'] })
  const ctx = await browser.newContext({ viewport: { width: 400, height: 800 }, hasTouch: true, isMobile: true })
  const page = await ctx.newPage()
  page.on('console', m => { if (/AIB|Error/.test(m.text())) console.log('   ', m.text()) })
  await page.route('https://test.local/', r => r.fulfill({ contentType: 'text/html', body: '<meta name=viewport content="width=device-width"><body style="margin:0"><video id=v muted autoplay playsinline src="/t.webm" style="width:400px;height:225px;display:block;margin-top:100px"></video></body>' }))
  await page.route('https://test.local/t.webm', r => r.fulfill({ contentType: 'video/webm', body: fs.readFileSync('/tmp/claude-0/t.webm') }))
  await page.addInitScript(() => { window.__calls = []; window.AIBNative = { playing: (a, w, h) => window.__calls.push(['playing', a, w, h]), brightness: d => { window.__calls.push(['b', d]); return 0.5 }, volume: d => { window.__calls.push(['v', d]); return 0.6 }, pip: () => window.__calls.push(['pip']) } })
  await page.goto('https://test.local/')
  await page.addScriptTag({ content: fs.readFileSync(ENGINE, 'utf8') })
  await page.waitForFunction(() => document.getElementById('v').readyState >= 2)
  await page.evaluate(() => { const v = document.getElementById('v'); let t = 20; window.__seeks = []; Object.defineProperty(v, 'currentTime', { get: () => t, set: x => { window.__seeks.push(x); t = x } }) })
  await page.waitForTimeout(300)
  const t0 = await page.evaluate(() => document.getElementById('v').currentTime)
  await page.touchscreen.tap(350, 210); await page.waitForTimeout(120); await page.touchscreen.tap(350, 210)
  await page.waitForTimeout(300)
  const t1 = await page.evaluate(() => document.getElementById('v').currentTime)
  await page.touchscreen.tap(40, 210); await page.waitForTimeout(120); await page.touchscreen.tap(40, 210)
  await page.waitForTimeout(300)
  const t2 = await page.evaluate(() => document.getElementById('v').currentTime)
  console.log('seeks:', JSON.stringify(await page.evaluate(() => window.__seeks)))
  console.log('double tap right: ' + t0.toFixed(1) + ' -> ' + t1.toFixed(1) + ' ; then left -> ' + t2.toFixed(1))
  await page.waitForTimeout(600)
  const bar = await page.evaluate(() => { const c = document.querySelector('[data-aib-ctl]'); return c && { display: c.style.display, buttons: Array.from(c.children).filter(b => b.style.display !== 'none').map(b => b.textContent) } })
  console.log('toolbar after touch:', JSON.stringify(bar))
  const speedBtn = await page.$('[data-aib-ctl] > div:nth-child(3)')
  await speedBtn.click(); await page.waitForTimeout(100)
  console.log('speed after one press:', await page.evaluate(() => document.getElementById('v').playbackRate))
  await page.waitForTimeout(1800)
  console.log('bridge playing report:', JSON.stringify(await page.evaluate(() => window.__calls.find(c => c[0] === 'playing'))))
  // swipe test (video made full-viewport so swipes are enabled)
  await page.evaluate(() => { const v = document.getElementById('v'); v.style.cssText = 'position:fixed;inset:0;width:100vw;height:100vh' })
  const cdp = await ctx.newCDPSession(page)
  const touch = async (type, x, y) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: type === 'touchEnd' ? [] : [{ x, y }] })
  await touch('touchStart', 300, 600); for (let y = 590; y >= 300; y -= 20) await touch('touchMove', 300, y); await touch('touchEnd')
  await touch('touchStart', 80, 600); for (let y = 590; y >= 400; y -= 20) await touch('touchMove', 80, y); await touch('touchEnd')
  const c = await page.evaluate(() => window.__calls)
  console.log('swipe right half -> volume calls:', c.filter(x => x[0] === 'v').length, ' left half -> brightness calls:', c.filter(x => x[0] === 'b').length)
  await page.evaluate(() => window.__aibPip(true))
  console.log('pip layout:', JSON.stringify(await page.evaluate(() => { const r = document.getElementById('v').getBoundingClientRect(); return [r.width, r.height] })))
  await page.evaluate(() => window.__aibPip(false))
  await browser.close()
})()
